import { triage } from './src/agents.js';

const chat = triage.chat();
const r1 = await chat.send('My order is A-1001.');
console.log('R1:', JSON.stringify(r1.text ?? r1, null, 2).slice(0, 500));
const sessionId = r1.sessionId ?? chat.sessionId;
console.log('sessionId:', sessionId);

const chat2 = await triage.loadChat({ sessionId });
const r2 = await chat2.send('What is the status of my order?');
console.log('R2:', JSON.stringify(r2.text ?? r2, null, 2).slice(0, 500));
EOF
